# --- the cases, shared verbatim with `gold408.py` (which ran them on the baseline) ------------------------------------
FAKE_HOME = "/nonexistent/syrd408/home"
SOURCES = {"the checkout fallback": None, "a home-relative source": "~/checkouts/../repo", "a source with ..": "/nonexistent/syrd408/a/../b"}
CASES = {}
for workflow in (True, False, None):
    for complete in (True, False):
        for roots in ((), ("the release root is not the owner's",), ("the release root is not the owner's", "current is a dangling link")):
            for blocked in ("", "the release is behind its target"):
                for source in SOURCES:
                    CASES[f"workflow {workflow}; cutover {'complete' if complete else 'incomplete'}; {len(roots)} root problems; "
                          f"release {'blocked' if blocked else 'clear'}; {source}"] = {
                        "workflow": workflow, "complete": complete, "roots": list(roots), "blocked": blocked, "source": SOURCES[source]}


class Status:
    """What the release report stand-in answers."""


def RUNNER(*args: object, **kwargs: object) -> object:
    raise AssertionError("the runner is only passed on")


def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """Run one case against `holder._finish_upgrade_preview`, every launcher seam standing in on `t`."""
    calls: list = []
    said: list = []
    config = SimpleNamespace(project="p408")
    status = Status()

    def say(line):
        said.append(line)
        calls.append(["say"])

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in value.items()}
        for obj, name in ((config, "CONFIG"), (RUNNER, "RUNNER"), (say, "SAY"), (status, "STATUS")):
            if value is obj:
                return name
        if isinstance(value, Path):
            return f"PATH {value}"
        if callable(value):
            return "ANOTHER CALLABLE"
        return value

    def seam(name, answer):
        def call(*args, **kwargs):
            reached.add(name)
            calls.append([name, norm(list(args)), norm(dict(sorted(kwargs.items())))])
            return answer(*args, **kwargs)
        return call

    def report(cfg, **kwargs):
        kwargs["print_func"]("current release: aaaa")
        kwargs["print_func"]("target release: bbbb")
        return status

    stand = {"install_handed_off_workflow": seam("install_handed_off_workflow", lambda *a, **k: spec["workflow"]),
             "current_user_name": seam("current_user_name", lambda: "syrd408-director-account"),
             "role_account_cutover": seam("role_account_cutover", lambda *a, **k: SimpleNamespace(is_complete=spec["complete"])),
             "owner_release_root_problems": seam("owner_release_root_problems", lambda *a, **k: list(spec["roots"])),
             "_repo_root": seam("_repo_root", lambda: Path("/nonexistent/syrd408/checkout/../repo")),
             "report_tenant_release_upgrade": seam("report_tenant_release_upgrade", report),
             "release_update_blocked": seam("release_update_blocked", lambda s: spec["blocked"])}
    saved = {n: getattr(t, n) for n in stand}
    saved_home = os.environ.get("HOME")
    for n, f in stand.items():
        setattr(t, n, f)
    os.environ["HOME"] = FAKE_HOME
    try:
        got = holder._finish_upgrade_preview(config, config_path=Path("/nonexistent/syrd408/p408.json"), director="director",
                                             source_repo=None if spec["source"] is None else Path(spec["source"]),
                                             commit_git_dir="/nonexistent/syrd408/git", deploy_ref="v408", runner=RUNNER, print_func=say)
        answer = norm(got)
    except AssertionError:
        raise
    except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
        answer = {"raised": type(exc).__name__, "message": str(exc)}
    finally:
        for n, f in saved.items():
            setattr(t, n, f)
        if saved_home is None:
            os.environ.pop("HOME", None)
        else:
            os.environ["HOME"] = saved_home
    return {"answer": answer, "said": said, "calls": calls}
# ----------------------------------------------------------------------------------------------------------------------


def check(condition: bool, detail: str) -> None:
    global CHECKS
    assert condition, detail
    CHECKS += 1


def python(probe: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run([sys.executable, "-c", probe], cwd=ROOT, capture_output=True, text=True,
                          env={"PATH": "/usr/bin:/bin"}, check=False)


class patched:
    def __init__(self, target: object, **values: object) -> None:
        self.target, self.values = target, values

    def __enter__(self) -> None:
        self.saved = {name: getattr(self.target, name) for name in self.values}
        for name, value in self.values.items():
            setattr(self.target, name, value)

    def __exit__(self, *exc: object) -> None:
        for name, value in self.saved.items():
            setattr(self.target, name, value)


def refuse(what: str):
    def refused(*args: object, **kwargs: object) -> object:
        raise AssertionError(f"{what} was called: {args} {kwargs}")
    return refused


HOMES = {workflow_adoption: ("install_handed_off_workflow",), role_identity_cutover: ("role_account_cutover",),
         tenant_release_root: ("owner_release_root_problems",), tenant_release_report: ("report_tenant_release_upgrade", "release_update_blocked")}


class contained:
    """Spawns, signals, account lookups and connections refused, and each seam's own definition."""

    def __enter__(self) -> None:
        self.parts = [patched(subprocess, run=refuse("subprocess.run"), Popen=refuse("subprocess.Popen")),
                      patched(os, kill=refuse("os.kill"), geteuid=refuse("os.geteuid")),
                      patched(pwd, getpwnam=refuse("pwd.getpwnam"), getpwuid=refuse("pwd.getpwuid")),
                      patched(socket.socket, connect=refuse("socket.connect"), connect_ex=refuse("socket.connect_ex")),
                      *(patched(home, **{name: refuse(f"{home.__name__}.{name}") for name in names}) for home, names in HOMES.items())]
        for part in self.parts:
            part.__enter__()

    def __exit__(self, *exc: object) -> None:
        for part in reversed(self.parts):
            part.__exit__(*exc)


def run(spec: dict) -> dict:
    with contained():
        return run_case(t, m, spec, REACHED)


def test_the_guard_itself_refuses_a_spawn_a_lookup_and_each_seam_past_the_launcher() -> None:
    attempts = [lambda: subprocess.run(["true"]), lambda: subprocess.Popen(["true"]), lambda: os.kill(os.getpid(), 0), lambda: os.geteuid(),
                lambda: pwd.getpwuid(0), lambda: socket.socket().connect(("127.0.0.1", 9)),
                *(lambda home=home, name=name: getattr(home, name)(SimpleNamespace(project="p408")) for home, names in HOMES.items() for name in names)]
    for attempt in attempts:
        with contained():
            try:
                attempt()
            except AssertionError as exc:
                refused = " was called: " in str(exc)
            else:
                refused = False
        check(refused, "the guard refuses a spawn, a signal, an account lookup, a connection, and each seam's own definition")


