def test_the_module_loads_nothing_of_switchyards_at_import() -> None:
    result = python("import sys, scripts.finish_upgrade_preview as m; "
                    "print(sorted(n for n in sys.modules if n.startswith('scripts.') and n != m.__name__))")
    check(result.returncode == 0 and result.stdout.strip() == "[]",
          f"it imports on its own and loads nothing else of Switchyard's: {result.stdout}{result.stderr[-400:]}")


def test_either_import_order_gives_one_object_and_the_signature() -> None:
    for order in (("scripts.finish_upgrade_preview", "scripts.team_launcher"), ("scripts.team_launcher", "scripts.finish_upgrade_preview")):
        result = python("import importlib, inspect; "
                        f"[importlib.import_module(n) for n in {order!r}]; "
                        "import scripts.team_launcher as t, scripts.finish_upgrade_preview as m; "
                        "s = inspect.signature(m._finish_upgrade_preview).parameters; "
                        "print(t._finish_upgrade_preview is m._finish_upgrade_preview, "
                        "list(s) == ['config', 'config_path', 'director', 'source_repo', 'commit_git_dir', 'deploy_ref', 'runner', 'print_func'] "
                        "and all(p.default is inspect.Parameter.empty for p in s.values()) "
                        "and [p.kind for p in s.values()][1:] == [inspect.Parameter.KEYWORD_ONLY] * 7, "
                        "not hasattr(m, 'ProjectConfig') and not hasattr(m, 'launcher'))")
        check(result.stdout.strip() == "True True True", f"{' then '.join(order)}: {result.stdout}{result.stderr[-600:]}")
    check(m.subprocess is subprocess and m.Path is Path, "the standard-library names are the module's own")


def test_the_seams_read_through_the_launcher_and_nothing_bound() -> None:
    tree = ast.parse((ROOT / "scripts" / "finish_upgrade_preview.py").read_text(encoding="utf-8"))
    node = next(n for n in tree.body if getattr(n, "name", None) == "_finish_upgrade_preview")
    through: dict[str, int] = {}
    for x in ast.walk(node):
        if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id == "launcher":
            through[x.attr] = through.get(x.attr, 0) + 1
    expected = SEAMS["_finish_upgrade_preview"]
    check(through == expected, f"each launcher name read through it exactly as often as before: {through}")
    imports = [ast.unparse(x) for x in ast.walk(node) if isinstance(x, (ast.Import, ast.ImportFrom))]
    check(imports == ["from scripts import team_launcher as launcher"] and ast.unparse(node.body[1]) == imports[0],
          f"the launcher imported once, first thing after the docstring, when it runs: {imports}")
    skip = {id(y) for part in [node.returns, *(a.annotation for a in node.args.args + node.args.kwonlyargs),
                               *(x.annotation for x in ast.walk(node) if isinstance(x, ast.AnnAssign)),
                               *(x.returns for x in ast.walk(node) if isinstance(x, ast.FunctionDef) and x is not node)]
            if part is not None for y in ast.walk(part)}
    bare = sorted({x.id for x in ast.walk(node) if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in expected and id(x) not in skip})
    check(bare == [], f"none of them read past it: {bare}")
    nested = [n.name for n in ast.walk(node) if isinstance(n, ast.FunctionDef) and n is not node]
    lambdas = [ast.unparse(n) for n in ast.walk(node) if isinstance(n, ast.Lambda)]
    check(nested == ["verdict"] and lambdas == ["lambda line: print_func(f'  {line}')"], f"the verdict closure and the indenting lambda stay inside: {nested} {lambdas}")
    fallback = [ast.unparse(k.value) for k in ast.walk(node) if isinstance(k, ast.keyword) and k.arg == "source_repo"]
    check(fallback == ["(source_repo or launcher._repo_root()).expanduser().resolve(strict=False)"], f"the source fallback, expanded and resolved: {fallback}")
    top = [ast.unparse(n) for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    tc = [ast.unparse(n) for n in tree.body if isinstance(n, ast.If)]
    check(top == ["from __future__ import annotations", "import subprocess", "from pathlib import Path", "from typing import TYPE_CHECKING, Any, Callable"]
          and tc == ["if TYPE_CHECKING:\n    from scripts.team_launcher import ProjectConfig"],
          f"only the standard library at the top, and the annotation's type under TYPE_CHECKING: {top} {tc}")
    check([n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))] == list(MOVED), "the one function, and nothing else")


def test_the_launcher_reexports_it_and_its_reader_reaches_it_there() -> None:
    tree = ast.parse((ROOT / "scripts" / "team_launcher.py").read_text(encoding="utf-8"))
    imports = [n for n in tree.body if isinstance(n, ast.ImportFrom) and n.module == "scripts.finish_upgrade_preview"]
    check(len(imports) == 1 and [(a.name, a.asname) for a in imports[0].names] == [("_finish_upgrade_preview", None)], "one explicit import of it, unaliased")
    check(imports[0].lineno < min(n.lineno for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))),
          "at the top, above every definition that could read it")
    defined = {getattr(n, "name", None) for n in tree.body} | {x.id for n in tree.body if isinstance(n, ast.Assign) for x in n.targets if isinstance(x, ast.Name)}
    # A neighbour stays reachable on the launcher: defined there, or -- once a later slice moves it on -- re-exported there, unaliased.
    exported = {a.name for n in tree.body if isinstance(n, ast.ImportFrom) and (n.module or "").startswith("scripts.")
                for a in n.names if a.asname is None}
    check(not defined & set(MOVED) and {"capture_installed_units", "_plan_data_from_config"} <= defined | exported,
          "the launcher does not define it, and keeps its neighbours, its own or re-exported")
    calls: dict = {}
    for fn in tree.body:
        if isinstance(fn, ast.FunctionDef):
            for x in ast.walk(fn):
                if isinstance(x, ast.Call) and ast.unparse(x.func).split(".")[-1] in MOVED:
                    calls.setdefault(fn.name, {}).setdefault(ast.unparse(x.func), 0)
                    calls[fn.name][ast.unparse(x.func)] += 1
    check(calls == DISPATCH, f"the launcher still calls it where it did (nowhere): {calls}")
    data = (ROOT / "scripts" / "director_upgrade.py").read_bytes()
    check(hashlib.sha1(b"blob %d\0" % len(data) + data).hexdigest() == DIRECTOR_UPGRADE_BLOB,
          "director_upgrade.py, which reads launcher._finish_upgrade_preview when it runs, is byte-identical to the baseline")
    uses = [ast.unparse(x) for x in ast.walk(ast.parse(data.decode())) if isinstance(x, ast.Attribute) and x.attr in MOVED]
    check(uses == ["launcher._finish_upgrade_preview"], f"and reads it through the launcher: {uses}")


